package com.stocksense.auth;
import com.stocksense.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; private final Map<String,Otp> otps=new ConcurrentHashMap<>(); record Register(@NotBlank String name,@Email String email,@Size(min=8) String password,Role role){} record Login(@Email String email,@NotBlank String password){} record Token(String token,String name,String email,Role role){} record EmailReq(@Email String email){} record ResetReq(@Email String email,@Pattern(regexp="\d{6}") String otp,@Size(min=8) String newPassword){} record Otp(String code,Instant expires){} @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.existsByEmailIgnoreCase(r.email()))return ResponseEntity.status(409).body(Map.of("message","Email already registered")); User u=new User();u.setName(r.name());u.setEmail(r.email().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));u.setRole(r.role()==null?Role.WAREHOUSE_STAFF:r.role());users.save(u);return ResponseEntity.ok(new Token(jwt.generate(u.getEmail()),u.getName(),u.getEmail(),u.getRole()));} @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Login r){return users.findByEmailIgnoreCase(r.email()).filter(u->encoder.matches(r.password(),u.getPasswordHash())).<ResponseEntity<?>>map(u->ResponseEntity.ok(new Token(jwt.generate(u.getEmail()),u.getName(),u.getEmail(),u.getRole()))).orElseGet(()->ResponseEntity.status(401).body(Map.of("message","Invalid credentials")));} @PostMapping("/forgot-password") public ResponseEntity<?> forgot(@Valid @RequestBody EmailReq r){if(users.existsByEmailIgnoreCase(r.email())){String code=String.format("%06d",new Random().nextInt(1_000_000));otps.put(r.email().toLowerCase(),new Otp(code,Instant.now().plusSeconds(300))); System.out.println("StockSense DEV OTP for "+r.email()+": "+code);} return ResponseEntity.ok(Map.of("message","If the email exists, an OTP was generated. In development, check backend console."));} @PostMapping("/reset-password") public ResponseEntity<?> reset(@Valid @RequestBody ResetReq r){Otp o=otps.get(r.email().toLowerCase()); if(o==null||Instant.now().isAfter(o.expires())||!o.code().equals(r.otp()))return ResponseEntity.badRequest().body(Map.of("message","Invalid or expired OTP")); User u=users.findByEmailIgnoreCase(r.email()).orElseThrow();u.setPasswordHash(encoder.encode(r.newPassword()));users.save(u);otps.remove(r.email().toLowerCase());return ResponseEntity.ok(Map.of("message","Password reset successful"));} }
